using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Playables;using UnityEngine.Animations;using Sandbox.CharacterSystem;using Newtonsoft.Json;
public static class VerifyV2CharacterSetup {
 // Evaluate skin matrices directly: BakeMesh's scale handling is ambiguous for
 // this delivery's 100x bone rigs. Include all influences and current shapes.
 static Vector3[] Bake(SkinnedMeshRenderer r,Transform root){
 var mesh=r.sharedMesh;var v=mesh.vertices;
 for(int shape=0;shape<mesh.blendShapeCount;shape++){float w=r.GetBlendShapeWeight(shape)/100f;if(Mathf.Abs(w)<1e-7f)continue;var delta=new Vector3[v.Length];mesh.GetBlendShapeFrameVertices(shape,0,delta,null,null);for(int j=0;j<v.Length;j++)v[j]+=delta[j]*w;}
 var bind=mesh.bindposes;var mat=r.bones.Select((b,j)=>root.worldToLocalMatrix*b.localToWorldMatrix*bind[j]).ToArray();var result=new Vector3[v.Length];
 using(var counts=mesh.GetBonesPerVertex())using(var weights=mesh.GetAllBoneWeights()){int at=0;for(int j=0;j<v.Length;j++){for(int k=0;k<counts[j];k++){var w=weights[at++];result[j]+=mat[w.boneIndex].MultiplyPoint3x4(v[j])*w.weight;}}}return result;}
 static float Difference(Vector3[] a,Vector3[] b){float max=0;for(int j=0;j<a.Length;j++)max=Mathf.Max(max,Vector3.Distance(a[j],b[j]));return max;}
 public static object Run(){
 if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit Mode required");var root=PrefabUtility.LoadPrefabContents("Assets/_Sandbox/Characters/Ethan_V2/Ethan_V2.prefab");
 try{
 var character=root.GetComponent<Character>();var flow=root.GetComponent<CharacterFlowController>();var errors=character.ValidateConfiguration();errors.AddRange(flow.ValidateConfiguration());if(errors.Count>0)throw new Exception(string.Join(";",errors));
 var animator=root.GetComponentInChildren<AnimationModule>(true).Animator;var bridge=root.GetComponent<CharacterSkeletonPoseBridge>();if(!animator.avatar.isHuman||!animator.avatar.isValid)throw new Exception("Invalid animation driver avatar");
 var lip=root.GetComponentInChildren<uLipSync.uLipSync>(true);var driver=root.GetComponentInChildren<uLipSync.uLipSyncBlendShape>(true);if(lip.onLipSyncUpdate.GetPersistentTarget(0)!=driver)throw new Exception("Lip-sync callback not remapped");
 var renderers=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Where(r=>new[]{"BAKED_head_lod0_mesh","BAKED_body_lod0_mesh","BAKED_Outfits_LOD0"}.Contains(r.name)).ToArray();var rest=renderers.ToDictionary(r=>r,BakeRenderer=>Bake(BakeRenderer,root.transform));bridge.ApplyPose();
 var neutral=renderers.ToDictionary(r=>r.name,r=>Difference(rest[r],Bake(r,root.transform)));if(neutral.Values.Max()>.001f)throw new Exception("Neutral mesh changed: "+JsonConvert.SerializeObject(neutral));
 var clips=AssetDatabase.FindAssets("t:AnimationDefinition",new[]{"Assets/_Sandbox"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<AnimationDefinition>).Where(d=>d&&d.Clip&&d.Clip.isHumanMotion).ToArray();
 var definition=clips.FirstOrDefault(d=>d.name.ToLowerInvariant().Contains("wav"))??clips.First();var clip=definition.Clip;
 var face=driver.skinnedMeshRenderer;int joy=face.sharedMesh.GetBlendShapeIndex("emo_joy");face.SetBlendShapeWeight(joy,23);
 var graph=PlayableGraph.Create("Disposable V2 retarget check");Dictionary<string,float> movement;
 try{graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);var playable=AnimationClipPlayable.Create(graph,clip);playable.SetApplyFootIK(false);var output=AnimationPlayableOutput.Create(graph,"V2 animation",animator);output.SetSourcePlayable(playable);graph.Play();playable.SetTime(clip.length*.45);graph.Evaluate(0);bridge.ApplyPose();movement=renderers.ToDictionary(r=>r.name,r=>Difference(rest[r],Bake(r,root.transform)));}
 finally{graph.Destroy();}
 File.WriteAllText("Data/EthanV2/CharacterSetup/pose_debug.json",JsonConvert.SerializeObject(bridge.Bindings.Select(p=>new{source=p.source.name,target=p.target.name,position=p.source.position.ToString("F4"),sourceScale=p.source.lossyScale.ToString("F4"),targetPosition=p.target.position.ToString("F4"),targetScale=p.target.lossyScale.ToString("F4"),delta=(root.transform.worldToLocalMatrix*p.source.localToWorldMatrix*p.sourceBindInverse).GetColumn(3).magnitude}).OrderByDescending(p=>p.delta).Take(20),Formatting.Indented));
 var body=renderers.First(r=>r.name=="BAKED_body_lod0_mesh");var verts=body.sharedMesh.vertices;var bw=body.sharedMesh.boneWeights;var binds=body.sharedMesh.bindposes;var matrices=body.bones.Select((b,j)=>root.transform.worldToLocalMatrix*b.localToWorldMatrix*binds[j]).ToArray();var cpu=new Vector3[verts.Length];for(int j=0;j<verts.Length;j++){var b=bw[j];cpu[j]=matrices[b.boneIndex0].MultiplyPoint3x4(verts[j])*b.weight0+matrices[b.boneIndex1].MultiplyPoint3x4(verts[j])*b.weight1+matrices[b.boneIndex2].MultiplyPoint3x4(verts[j])*b.weight2+matrices[b.boneIndex3].MultiplyPoint3x4(verts[j])*b.weight3;}
 File.WriteAllText("Data/EthanV2/CharacterSetup/skin_debug.json",JsonConvert.SerializeObject(new{cpuMaximum=cpu.Max(v=>v.magnitude),restMaximum=rest[body].Max(v=>v.magnitude),bakeMaximum=Bake(body,root.transform).Max(v=>v.magnitude),bodyScale=body.transform.lossyScale.ToString(),rootBone=body.rootBone.name,rootScale=body.rootBone.lossyScale.ToString()},Formatting.Indented));
 if(movement.Values.Max()>2f||movement["BAKED_body_lod0_mesh"]<.005f||movement["BAKED_Outfits_LOD0"]<.005f)throw new Exception("Visible body/clothing motion invalid: "+JsonConvert.SerializeObject(movement));
 if(Mathf.Abs(face.GetBlendShapeWeight(joy)-23)>.001f)throw new Exception("Body clip overwrote facial expression");
 var phaseSamples=new List<object>();foreach(var d in clips.Where(d=>d.name.ToLowerInvariant().Contains("think")||d.name.ToLowerInvariant().Contains("idle"))){var g=PlayableGraph.Create("Disposable phase sample");try{g.SetTimeUpdateMode(DirectorUpdateMode.Manual);var p=AnimationClipPlayable.Create(g,d.Clip);p.SetApplyFootIK(false);var output=AnimationPlayableOutput.Create(g,"phase",animator);output.SetSourcePlayable(p);g.Play();p.SetTime(d.Clip.length*.4);g.Evaluate(0);bridge.ApplyPose();var positions=Bake(renderers.First(r=>r.name=="BAKED_body_lod0_mesh"),root.transform);float bound=positions.Max(v=>v.magnitude);if(float.IsNaN(bound)||bound>4)throw new Exception("Phase pose out of bounds: "+d.name);phaseSamples.Add(new{definition=d.name,clip=d.Clip.name,maximumVertexRadiusM=bound});}finally{g.Destroy();}}
 var sync=root.GetComponent<CharacterFacialMeshSync>();if(!sync)throw new Exception("Facial sync missing");var secondary=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Where(r=>r!=face&&r.name!="BAKED_body_lod0_mesh"&&r.name!="BAKED_Outfits_LOD0"&&r.sharedMesh.blendShapeCount==73).ToArray();
 for(int i=0;i<73;i++)face.SetBlendShapeWeight(i,0);sync.Apply();int synchronizedChecks=0;for(int i=0;i<73;i++){face.SetBlendShapeWeight(i,37);sync.Apply();foreach(var other in secondary){int j=other.sharedMesh.GetBlendShapeIndex(face.sharedMesh.GetBlendShapeName(i));if(j<0||Mathf.Abs(other.GetBlendShapeWeight(j)-37)>.001f)throw new Exception("Secondary facial shape did not follow");synchronizedChecks++;}face.SetBlendShapeWeight(i,0);sync.Apply();}
 var result=new{passed=true,configurationErrors=errors,avatar=animator.avatar.name,humanoid=true,bindings=bridge.Bindings.Count,neutralErrorsM=neutral,sampledClip=clip.name,visibleMeshMovementM=movement,phaseSamples,faceExpressionPreserved=true,lipSyncCallbackRemapped=true,phonemes=driver.blendShapes.Count,synchronizedFacialMeshes=secondary.Length,synchronizedChecks,playModeTested=false};
 File.WriteAllText("Data/EthanV2/CharacterSetup/verification.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }finally{PrefabUtility.UnloadPrefabContents(root);}}
}

